  legenda.appendChild(el('span', {}, [el('span', { class: 'swatch', style: 'background:#1baf7a' }), document.createTextNode('Fretes e Carretos — ' + formatMoeda(mapaRegra.fretes_carretos))]));
  cardRegra.appendChild(legenda);
